import pandas as pd
import sys

path = "budget.xlsx"

# Inspect structure
xls = pd.ExcelFile(path)
print("SHEETS:", xls.sheet_names)

for sheet in xls.sheet_names:
    df = pd.read_excel(path, sheet_name=sheet, header=None)
    print(f"\n=== Sheet: {sheet} ({df.shape[0]} rows x {df.shape[1]} cols) ===")
    print(df.head(15).to_string())

# Determine category column and amount columns dynamically
for sheet in xls.sheet_names:
    df = pd.read_excel(path, sheet_name=sheet)
    cols = {str(c).strip().lower(): c for c in df.columns}
    cat_col = None
    for key in ("category", "categoria", "kategorie", "expense category"):
        if key in cols:
            cat_col = cols[key]
            break
    amount_cols = []
    for key in ("amount", "cost", "expense", "price", "value", "total", "spent"):
        if key in cols:
            amount_cols.append(cols[key])
    if not amount_cols:
        for c in df.columns:
            if pd.api.types.is_numeric_dtype(df[c]) and c != cat_col:
                amount_cols.append(c)
    print(f"\n--- Analysis sheet: {sheet} ---")
    print("Category column:", cat_col, "| Amount columns:", amount_cols)
    if cat_col is not None and amount_cols:
        result = df.copy()
        result["_total"] = result[amount_cols].sum(axis=1, skipna=True)
        grouped = result.groupby(cat_col, dropna=False)["_total"].sum()
        print(grouped.to_string())
        print("GRAND TOTAL:", result["_total"].sum())
    else:
        numeric = df.select_dtypes(include="number")
        if not numeric.empty:
            print("Column totals:")
            print(numeric.sum().to_string())
            print("GRAND TOTAL:", numeric.sum().sum())

from openpyxl import load_workbook

wb = load_workbook("budget.xlsx", data_only=True)
for ws in wb.worksheets:
    print(f"Sheet: {ws.title} | max_row={ws.max_row} | max_col={ws.max_column}")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{ws.title}!{cell.coordinate}: {cell.value!r}")

