import sys
from openpyxl import load_workbook

path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
wb = load_workbook(path, data_only=True, read_only=True)

for ws in wb.worksheets:
    rows = list(ws.iter_rows(values_only=True))
    header = rows[0]
    print(f"Sheet: {ws.title} | header: {header}")

    cat_idx = None
    amt_idx = None
    for i, h in enumerate(header):
        hs = str(h).strip().lower() if h is not None else ""
        if cat_idx is None and ("categor" in hs or "item" in hs or "type" in hs):
            cat_idx = i
        if amt_idx is None and any(k in hs for k in ("amount", "expense", "cost", "value", "price", "total")):
            amt_idx = i

    if cat_idx is not None and amt_idx is not None:
        total = 0.0
        for row in rows[1:]:
            if len(row) > amt_idx:
                v = row[amt_idx]
                if isinstance(v, (int, float)):
                    total += v
        print(f"TOTAL_EXPENSES[{ws.title}] = {total}")
    else:
        nums = [v for row in rows[1:] for v in row if isinstance(v, (int, float))]
        print(f"TOTAL_NUMERIC[{ws.title}] = {sum(nums)}")

